import React, { useState } from "react";
import { useNavigate, useLocation } from "react-router-dom";

const PRIMARY = "#EA580C";
const PRIMARY_LIGHT = "#FFF4EE";
const PRIMARY_TEXT = "#EA580C";

export type NavItem = {
  id: string;
  label: string;
  path: string;
  icon?: string;
};

export type NavGroup = {
  id: string;
  label: string;
  path: string;
  icon?: string;
  children?: NavItem[];
};

interface SidebarProps {
  features: NavGroup[];
  collapsed?: boolean;
  onToggle?: () => void;
  onNavigate?: (item: NavItem) => void;
}

const WeeraIcon: React.FC<{ size?: number }> = ({ size = 22 }) => (
  <img
    src="/images/app_icon_fg.png"
    width={size}
    height={size}
    alt="Weera logo"
    style={{
      objectFit: "contain",
      display: "block",
    }}
  />
);

export const Sidebar: React.FC<SidebarProps> = ({
  features,
  collapsed = false,
  onToggle,
  onNavigate,
}) => {
  const navigate = useNavigate();
  const location = useLocation();

  const [openGroups, setOpenGroups] = useState<Record<string, boolean>>({
    users: true,
  });

  const width = collapsed ? 76 : 280;

  const handleClick = (item: NavItem) => {
    navigate(item.path);
    onNavigate?.(item);
  };

  const toggleGroup = (groupId: string) => {
    setOpenGroups((prev) => ({
      ...prev,
      [groupId]: !prev[groupId],
    }));
  };

  const isPathActive = (path: string) => {
    return location.pathname === path;
  };

  return (
    <aside
      style={{
        width,
        minWidth: width,
        height: "100vh",
        background: "#F9FBFC",
        borderRight: "1px solid #E2E8F0",
        display: "flex",
        flexDirection: "column",
        transition: "all 0.25s ease",
        overflow: "hidden",
        position: "fixed",
        left: 0,
        top: 0,
        zIndex: 100,
        boxSizing: "border-box",
      }}
    >
      {/* HEADER */}
      <div
        style={{
          height: 72,
          padding: collapsed ? "12px 10px" : "12px 16px",
          display: "flex",
          alignItems: "center",
          justifyContent: collapsed
            ? "center"
            : "space-between",
          borderBottom: "1px solid #E2E8F0",
        }}
      >
        {!collapsed ? (
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: 10,
            }}
          >
            <div
              style={{
                width: 38,
                height: 38,
                borderRadius: 10,
                background: PRIMARY,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                boxShadow: `0 2px 10px ${PRIMARY}40`,
              }}
            >
              <WeeraIcon size={28} />
            </div>

            <span
              style={{
                fontWeight: 700,
                fontSize: 16,
                color: "#0F172A",
              }}
            >
              WEERA
            </span>
          </div>
        ) : (
          <div
            style={{
              width: 42,
              height: 42,
              borderRadius: 12,
              background: PRIMARY,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              boxShadow: `0 2px 10px ${PRIMARY}40`,
            }}
          >
            <WeeraIcon size={28} />
          </div>
        )}

        {/* TOGGLE */}
        {!collapsed && (
          <button
            onClick={onToggle}
            aria-label="Toggle sidebar"
            style={{
              width: 36,
              height: 36,
              borderRadius: 10,
              border: "1px solid #E2E8F0",
              background: "#fff",
              cursor: "pointer",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              fontSize: 18,
              color: "#475569",
              flexShrink: 0,
            }}
          >
            ☰
          </button>
        )}
      </div>

      {/* COLLAPSED TOGGLE BUTTON */}
      {collapsed && (
        <div
          style={{
            display: "flex",
            justifyContent: "center",
            padding: "10px 0",
          }}
        >
          <button
            onClick={onToggle}
            aria-label="Expand sidebar"
            style={{
              width: 42,
              height: 42,
              borderRadius: 10,
              border: "1px solid #E2E8F0",
              background: "#fff",
              cursor: "pointer",
              fontSize: 18,
              color: "#475569",
            }}
          >
            ☰
          </button>
        </div>
      )}

      {/* NAVIGATION */}
      <nav
        style={{
          flex: 1,
          overflowY: "auto",
          padding: "12px 8px",
        }}
      >
        <ul
          style={{
            listStyle: "none",
            padding: 0,
            margin: 0,
            display: "flex",
            flexDirection: "column",
            gap: 8,
          }}
        >
          {features.map((group) => {
            const groupActive =
              location.pathname.startsWith(group.path);

            const hasChildren = !!group.children?.length;

            const isOpen = openGroups[group.id];

            return (
              <React.Fragment key={group.id}>
                {/* PARENT */}
                <li>
                  <button
                    onClick={() => {
                      if (hasChildren && !collapsed) {
                        toggleGroup(group.id);
                      } else {
                        handleClick({
                          id: group.id,
                          label: group.label,
                          path: group.path,
                          icon: group.icon,
                        });
                      }
                    }}
                    title={collapsed ? group.label : undefined}
                    style={{
                      width: "100%",
                      height: 50,
                      border: "none",
                      borderRadius: 12,
                      cursor: "pointer",
                      display: "flex",
                      alignItems: "center",
                      justifyContent: collapsed
                        ? "center"
                        : "flex-start",
                      gap: 12,
                      padding: collapsed
                        ? "0"
                        : "0 14px",
                      background: groupActive
                        ? PRIMARY_LIGHT
                        : "transparent",
                      color: groupActive
                        ? PRIMARY_TEXT
                        : "#475569",
                      fontWeight: groupActive ? 600 : 500,
                      transition: "all 0.2s ease",
                    }}
                  >
                    <span
                      style={{
                        fontSize: 20,
                        flexShrink: 0,
                      }}
                    >
                      {group.icon}
                    </span>

                    {!collapsed && (
                      <>
                        <span>{group.label}</span>

                        {hasChildren && (
                          <span
                            style={{
                              marginLeft: "auto",
                              fontSize: 12,
                            }}
                          >
                            {isOpen ? "▾" : "▸"}
                          </span>
                        )}
                      </>
                    )}
                  </button>
                </li>

                {/* CHILDREN */}
                {!collapsed &&
                  hasChildren &&
                  isOpen &&
                  group.children?.map((child) => {
                    const childActive = isPathActive(
                      child.path
                    );

                    return (
                      <li
                        key={child.id}
                        style={{
                          paddingLeft: 18,
                        }}
                      >
                        <button
                          onClick={() => handleClick(child)}
                          style={{
                            width: "100%",
                            height: 42,
                            border: "none",
                            borderRadius: 10,
                            cursor: "pointer",
                            display: "flex",
                            alignItems: "center",
                            gap: 10,
                            padding: "0 14px",
                            background: childActive
                              ? PRIMARY_LIGHT
                              : "transparent",
                            color: childActive
                              ? PRIMARY_TEXT
                              : "#64748B",
                            fontWeight:
                              childActive ? 600 : 400,
                            transition: "all 0.2s ease",
                          }}
                        >
                          <span>{child.label}</span>
                        </button>
                      </li>
                    );
                  })}
              </React.Fragment>
            );
          })}
        </ul>
      </nav>
    </aside>
  );
};

export default Sidebar;
